using CosmicBlock.Audio;
using CosmicBlock.UI;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
public static class SettingsPolishBuilder {
 const string Characters="게임을 종료할까요?현재 게임은 저장되어 다음에 이어서 플레이할 수 있어요.취소종료홈으로 돌아갈까요?진행 중인 게임은 저장돼요.홈에서 이어서 플레이할 수 있어요.계속하기설정배경음악효과음음악 볼륨진동닫기ONOFF0123456789%";
 public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");var medium=Font("Medium");var semi=Font("SemiBold");var flow=Object.FindAnyObjectByType<GameFlowController>();var panel=flow.HomeRoot.transform.Find("SettingsPanel");panel.gameObject.SetActive(false);var card=panel.Find("Card");foreach(var image in card.GetComponentsInChildren<Image>(true))if(image.name=="ThemeFill")Object.DestroyImmediate(image.gameObject);foreach(var effect in card.GetComponents<Shadow>())Object.DestroyImmediate(effect);if(card.GetComponent<Image>()!=null)Object.DestroyImmediate(card.GetComponent<Image>());if(panel.GetComponent<Image>()!=null)Object.DestroyImmediate(panel.GetComponent<Image>());var dim=Node(panel,"DimOverlay");dim.SetAsFirstSibling();(dim.GetComponent<Image>()??dim.gameObject.AddComponent<Image>()).color=new Color(0,0,0,.72f);
  var frame=Node(card,"CosmicFrame");frame.SetAsFirstSibling();Place(frame,0,0,1,1);Mesh(frame,new Color(.063f,.102f,.18f),new Color(.81f,.70f,.43f,.5f),false);
  var titleNode=card.Find("Title")??card.Find("TitleText");titleNode.name="TitleText";var title=Text(titleNode,"설정",semi);title.color=new Color(.94f,.85f,.66f);Place((RectTransform)titleNode,.1f,.83f,.9f,.92f);
  var oldSfx=card.Find("Sfx");if(oldSfx!=null)Object.DestroyImmediate(oldSfx.gameObject);var haptic=Text(card.Find("Haptic"),"진동  ON",medium);Place(haptic.rectTransform,.1f,.24f,.9f,.30f);
  var controls=card.Find("AudioControls");var bgm=controls.Find("BgmToggle");var sfx=controls.Find("SfxToggle");StyleButton(bgm,false);StyleButton(sfx,false);Place((RectTransform)bgm,.10f,.67f,.90f,.77f);Place((RectTransform)sfx,.10f,.34f,.90f,.44f);var bgmText=Text(bgm.Find("Label"),"",semi);var sfxText=Text(sfx.Find("Label"),"",semi);var volumeText=Text(controls.Find("VolumeLabel"),"",medium);Place(volumeText.rectTransform,.1f,.58f,.9f,.64f);
  var close=card.Find("Close");StyleButton(close,true);Place((RectTransform)close,.3f,.08f,.7f,.18f);Text(close.Find("Text")??close.Find("Label"),"닫기",semi).color=new Color(.09f,.125f,.20f);
  var sliderNode=controls.Find("BgmVolume");Place((RectTransform)sliderNode,.12f,.475f,.88f,.565f);sliderNode.GetComponent<Image>().color=Color.clear;var track=Node(sliderNode,"Track");track.SetAsFirstSibling();Place(track,0,.40f,1,.60f);Mesh(track,new Color(.04f,.10f,.18f),new Color(.20f,.35f,.45f,.7f),false);var fillArea=Node(sliderNode,"FillArea");Place(fillArea,0,.40f,1,.60f);var fill=(RectTransform)(sliderNode.Find("FillArea/Fill")??sliderNode.Find("Fill"));fill.SetParent(fillArea,false);Place(fill,0,0,1,1);Mesh(fill,new Color(.24f,.73f,.85f),new Color(.24f,.73f,.85f),false);var handleArea=Node(sliderNode,"HandleArea");Place(handleArea,0,.5f,1,.5f);var handle=(RectTransform)(sliderNode.Find("HandleArea/Handle")??sliderNode.Find("Handle"));handle.SetParent(handleArea,false);Place(handle,.5f,.5f,.5f,.5f);var knob=Mesh(handle,new Color(.788f,.698f,.482f),new Color(.788f,.698f,.482f),true);var slider=sliderNode.GetComponent<Slider>();slider.targetGraphic=knob;
  controls.GetComponent<AudioSettingsView>().Configure(Object.FindAnyObjectByType<BackgroundMusicController>(),bgm.GetComponent<Button>(),sfx.GetComponent<Button>(),slider,bgmText,sfxText,volumeText);var style=card.GetComponent<PopupTypography>()??card.gameObject.AddComponent<PopupTypography>();style.Configure(medium,semi,new[]{volumeText,haptic});var layout=card.GetComponent<SettingsPopupLayout>()??card.gameObject.AddComponent<SettingsPopupLayout>();layout.Apply();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("SETTINGS_POLISH_APPLIED");EditorApplication.Exit(0);
 }
 static TMP_FontAsset Font(string weight){var f=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/CosmicPopup"+weight+".asset");f.atlasPopulationMode=AtlasPopulationMode.Dynamic;f.ClearFontAssetData();if(!f.TryAddCharacters(Characters))throw new System.Exception("Missing setting glyphs "+weight);f.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(f);foreach(var atlas in f.atlasTextures)EditorUtility.SetDirty(atlas);return f;}
 static RectTransform Node(Transform parent,string name){var t=parent.Find(name);if(t!=null)return (RectTransform)t;var go=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));go.transform.SetParent(parent,false);return (RectTransform)go.transform;}
 static TextMeshProUGUI Text(Transform node,string value,TMP_FontAsset font){var legacy=node.GetComponent<Text>();if(legacy!=null)Object.DestroyImmediate(legacy);var text=node.GetComponent<TextMeshProUGUI>()??node.gameObject.AddComponent<TextMeshProUGUI>();text.font=font;text.text=value;text.raycastTarget=false;text.color=new Color(.80f,.85f,.93f);text.alignment=TextAlignmentOptions.Center;return text;}
 static HomeQuitMeshGraphic Mesh(Transform node,Color fill,Color border,bool hit){if(node.GetComponent<Image>()!=null)Object.DestroyImmediate(node.GetComponent<Image>());foreach(var effect in node.GetComponents<Shadow>())Object.DestroyImmediate(effect);var g=node.GetComponent<HomeQuitMeshGraphic>()??node.gameObject.AddComponent<HomeQuitMeshGraphic>();g.Style(fill,border,10,1);g.raycastTarget=hit;g.color=Color.white;return g;}
 static void StyleButton(Transform t,bool gold){var g=Mesh(t,gold?new Color(.788f,.698f,.482f):new Color(.09f,.192f,.267f),gold?new Color(.788f,.698f,.482f):new Color(.235f,.427f,.514f),true);t.GetComponent<Button>().targetGraphic=g;var label=t.Find("Text")??t.Find("Label");if(label!=null)Place((RectTransform)label,0,0,1,1);}
 static void Place(RectTransform r,float x0,float y0,float x1,float y1){r.anchorMin=new Vector2(x0,y0);r.anchorMax=new Vector2(x1,y1);r.offsetMin=r.offsetMax=Vector2.zero;}
}

